import{z as o,x as s,o as t,c as p,q as A,j as i,D as a,d as r,s as n,S as l,b as E}from"./chunks/framework.C8m1ZpeB.js";const g=JSON.parse('{"title":"checkpoint 工程深入","description":"","frontmatter":{"title":"checkpoint 工程深入","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/ti-checkpoint-engineering.md","filePath":"llm/ti-checkpoint-engineering.md","lastUpdated":1791063341000}'),d={name:"llm/ti-checkpoint-engineering.md"};function c(h,e,m,D,C,u){const B=s("Mermaid");return t(),p("div",null,[e[2]||(e[2]=A('<h1 id="checkpoint-工程深入" tabindex="-1">checkpoint 工程深入 <a class="header-anchor" href="#checkpoint-工程深入" aria-label="Permalink to &quot;checkpoint 工程深入&quot;">​</a></h1><div class="epigraph"><p>检查点不是「保存」这个动作，而是一套存储系统：有层级、有带宽预算、有保留策略，还要定期演练——没人恢复过的检查点等于不存在。</p><footer>—— 据 PyTorch Distributed Checkpoint、Megatron-LM 与大规模训练容错实践整理</footer></div><p><a href="/llm/ti-data-pipeline">上一课</a>把数据侧收成三本账，流水线挂在前向之前。step 骨架上还剩一件每 \\(K\\) 步触发、却要为整场训练兜底的东西：检查点。保存清单与原子发布在 <a href="/llm/pretrain-ckpt">Checkpoint 与 resume</a> 已写全——参数、优化器、日程、缩放器、RNG、数据进度一样不能少。本课不再讲「存什么」，讲「怎么运营」：存到哪、多久存、坏了怎么知道、发布怎么走，以及这堆快照的账。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>清单正确只是及格线，运营层面有四个更深的坑。<strong>层级错位</strong>：直接写对象存储，HBM 到网络的带宽被序列化挤占，<a href="/llm/checkpoint-io-bandwidth">检查点 I/O 带宽</a>的账没有先算。<strong>策略错配</strong>：间隔凭感觉定，与<a href="/llm/large-scale-failure-rate">万卡训练的故障率</a>给出的实际 MTBF 对不上——故障间隔两天的机群，按一周一存的策略，每次事故平均回滚半周。<strong>完整性错觉</strong>：「写入无报错」被当成「可恢复」，坏盘产生的静默损坏、部分 rank 失败产生的拼接残片，都要等到真出事那天才暴露。<strong>发布混线</strong>：对外发布的仅权重转换与研究 resume 争用同一份权威快照，转换任务把训练目录写坏。</p><h3 id="存储层级与保留策略" tabindex="-1">存储层级与保留策略 <a class="header-anchor" href="#存储层级与保留策略" aria-label="Permalink to &quot;存储层级与保留策略&quot;">​</a></h3><p>生产配置分三级：本地 NVMe 做一级落点（吃掉序列化峰值），集群文件系统做二级（供本机群快速 resume），对象存储做三级（防整机群事故与机房级故障）。异步上传必须先冻结快照再刷盘，撕裂问题在<a href="/llm/async-checkpointing">异步检查点</a>已写。保留按双环：近环保最近 \\(N\\) 个高频点，远环保里程碑（每 \\(K\\) 步、退火起点、评测峰值点）。删环要有台账——「哪个作业的哪些快照占了多少 TB」若无人能答，存储预算必然失控。</p><p><span class="marginnote">术语翻译：MTBF（Mean Time Between Failures，平均无故障间隔）就是机群「平均多久坏一次」的实测值。存检查点的合理间隔大约是把它再除以一个安全系数——机群两天坏一次，就别一周才存一次，否则每次事故平均白干三天。</span></p><p><span class="marginnote">量级账：7B 模型混合精度全状态约 16 字节每参数，单点约 112 GB；4M token 批次跑 1T token 共 25 万步，若每 1000 步一存，近环 10 个点就要 1.1 TB，外加里程碑与转换副本——检查点存储超过数据集存储是常态，预算要单列。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>四件事把坑补上。其一，频率自动化：间隔由观测到的 MTBF 除以安全系数动态给出，写入策略配置而不是写死在代码里。其二，校验与演练：每个快照写校验和并登记 complete 标记；CI 里常驻一条 <strong>resume drill</strong>——训几十步、存、换卡数加载（走<a href="/llm/distributed-ckpt-format">分布式检查点格式</a>的 reshard）、续训，断言逐步损失连续；演练不过的作业不许上机群。其三，发布分线：仅权重导出与 <a href="/llm/ema-checkpoint-averaging">EMA 与检查点平均</a>一类的派生加工，从权威快照单向生成、单独存放，派生失败不触碰训练目录。其四，元数据完备：每个快照记录配置哈希、数据指纹、loss 快照，让「从哪一份恢复」成为可查询的决策而不是考古。</p>',11)),(t(),i(l,null,{default:a(()=>[n(B,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%AD%A5%20K%20%E8%A7%A6%E5%8F%91%22%5D%20--%3E%20FZ%5B%22%E5%86%BB%E7%BB%93%E5%BF%AB%E7%85%A7%E5%88%B0%20NVMe%22%5D%0A%20%20FZ%20--%3E%20CV%7B%22%E6%A0%A1%E9%AA%8C%E5%92%8C%20%2B%20complete%20%E6%A0%87%E8%AE%B0%22%7D%0A%20%20CV%20--%3E%7C%E9%80%9A%E8%BF%87%7C%20L2%5B%22%E5%BC%82%E6%AD%A5%E4%B8%8A%E9%9B%86%E7%BE%A4%20FS%22%5D%0A%20%20L2%20--%3E%20L3%5B%22%E5%BC%82%E6%AD%A5%E4%B8%8A%E5%AF%B9%E8%B1%A1%E5%AD%98%E5%82%A8%22%5D%0A%20%20CV%20--%3E%7C%E5%A4%B1%E8%B4%A5%7C%20AL%5B%22%E5%91%8A%E8%AD%A6%E5%B9%B6%E4%BF%9D%E6%8C%81%E4%B8%8A%E4%B8%80%20complete%22%5D%0A%20%20L3%20--%3E%20RET%5B%22%E6%8C%89%E5%8F%8C%E7%8E%AF%E4%BF%9D%E7%95%99%E4%B8%8E%E5%8F%B0%E8%B4%A6%E6%B8%85%E7%90%86%22%5D%0A%20%20DR%5B%22%E5%AE%9A%E6%9C%9F%20resume%20drill%3A%20%E6%8D%A2%E6%8B%93%E6%89%91%E5%8A%A0%E8%BD%BD%E7%BB%AD%E8%AE%AD%22%5D%20--%3E%20Q%5B%22%E6%BC%94%E7%BB%83%E4%B8%8D%E8%BF%87%E4%B8%8D%E8%AE%B8%E4%B8%8A%E4%BA%A7%E7%BA%BF%22%5D%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=E("p",null,"演练为什么是唯一可信的完整性证明：检查点的价值只有在恢复时兑现，而损坏模式（静默位翻转、部分写入、元数据与张量错版本）没有一种能靠「保存时没报错」排除。演练把「恢复」变成每周执行的代码路径，发现的是真实可恢复性，包括 reshard 正确性与 RNG 接续。三级层级为什么值得：恢复速度决定故障成本——一级本地恢复以分钟计，三级跨区恢复以小时计，层级让常见故障走快路、罕见故障走慢路，用存储钱换停机时间。",-1)),e[5]||(e[5]=E("p",null,"发布分线的机制与实验纪律同源：权威快照是「训练发生了什么」的事实，派生物是「我们想让别人拿到什么」的观点；两者混在一个目录，等于允许观点污染事实。",-1)),e[6]||(e[6]=E("p",null,"不同故障走不同恢复路径，代价不同：",-1)),(t(),i(l,null,{default:a(()=>[n(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20F%5B%22%E8%AE%AD%E7%BB%83%E4%B8%AD%E6%96%AD%22%5D%20--%3E%20T%7B%22%E5%9D%8F%E5%88%B0%E4%BB%80%E4%B9%88%E7%A8%8B%E5%BA%A6%3F%22%7D%0A%20%20T%20--%3E%7C%22%E5%8D%95%E5%8D%A1%20%2F%20%E5%8D%95%E6%9C%BA%E6%95%85%E9%9A%9C%22%7C%20T1%5B%22%E4%B8%80%E7%BA%A7%3A%20%E6%9C%AC%E5%9C%B0%20NVMe%2C%20%E5%88%86%E9%92%9F%E7%BA%A7%E6%81%A2%E5%A4%8D%22%5D%0A%20%20T%20--%3E%7C%22%E6%9C%BA%E7%BE%A4%20FS%20%E6%88%96%E5%A4%9A%E8%8A%82%E7%82%B9%E6%95%85%E9%9A%9C%22%7C%20T2%5B%22%E4%BA%8C%E7%BA%A7%3A%20%E9%9B%86%E7%BE%A4%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F%2C%20%E5%8D%81%E5%88%86%E9%92%9F%E7%BA%A7%22%5D%0A%20%20T%20--%3E%7C%22%E6%9C%BA%E6%88%BF%E7%BA%A7%E4%BA%8B%E6%95%85%20%2F%20%E7%9B%AE%E5%BD%95%E8%A2%AB%E8%AF%AF%E5%88%A0%22%7C%20T3%5B%22%E4%B8%89%E7%BA%A7%3A%20%E5%AF%B9%E8%B1%A1%E5%AD%98%E5%82%A8%2C%20%E5%B0%8F%E6%97%B6%E7%BA%A7%22%5D%0A%20%20T1%20--%3E%20R%5B%22%E5%8A%A0%E8%BD%BD%E5%90%8E%E6%96%AD%E8%A8%80%20loss%20%E8%BF%9E%E7%BB%AD%E5%86%8D%E7%BB%A7%E7%BB%AD%22%5D%0A%20%20T2%20--%3E%20R%0A%20%20T3%20--%3E%20R%0A"})]),fallback:a(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=A('<p><span class="marginnote">直觉类比：三级层级像放钱——零钱放钱包（NVMe，随取随用），积蓄放家里保险柜（集群 FS，要回家取），房产证放银行金库（对象存储，最慢但连房子着火都不怕）。日常故障走快路，罕见灾难走慢路，各付各的代价。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重复保存清单本身，也不管激活重计算——<a href="/llm/activation-checkpointing">激活重计算</a>是显存换算力的 autograd 手段，与作业级快照同名不同物，监控与文档里必须分开说。恢复也有极限：换框架大版本、换并行方案之外的结构改动，rescue 不回来，只能当新实验重开。跨机群迁移、与数据游标对接的细节分别归分布式与数据两课的口径。</p><p><span class="marginnote">常见误区：初学者容易把「checkpoint」一个词当成一回事——训练里的激活重计算检查点（为省显存，前向中丢激活、反向时重算）和作业级快照（为容灾，把参数与优化器状态落盘）完全不同，前者不产生任何可恢复的文件，挂了就挂了。排查「为什么没存下东西」之前，先确认说的是哪一个。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>检查点运营四件套：三级存储层级、按 MTBF 定频、双环保留加台账、派生发布分线。</li><li>完整性靠校验和加定期 resume drill，换拓扑加载是演练的必选项。</li><li>单点全状态约 16 字节每参数，检查点存储预算单列，常超数据集。</li><li>权威快照只写不改，派生物单向生成，事实与发布不混目录。</li><li>出处：PyTorch Distributed Checkpoint 文档；Megatron-LM（Shoeybi et al., 2019）；据大规模训练容错实践整理。</li></ul>',6))])}const F=o(d,[["render",c]]);export{g as __pageData,F as default};
